/**
 * @file lvgl.h
 * @brief Minimal LVGL type definitions shim for bare-metal compatibility.
 * Allows C image and font arrays generated by LVGL converters to compile
 * cleanly in STM32CubeIDE without requiring the full LVGL library.
 */

#ifndef LVGL_H_
#define LVGL_H_

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#ifndef LV_COLOR_DEPTH
#define LV_COLOR_DEPTH 16
#endif

#ifndef LV_COLOR_16_SWAP
#define LV_COLOR_16_SWAP 0
#endif

#define LV_COLOR_SIZE 16

/* Alignment and storage attributes */
#ifndef LV_ATTRIBUTE_MEM_ALIGN
#define LV_ATTRIBUTE_MEM_ALIGN
#endif

#ifndef LV_ATTRIBUTE_LARGE_CONST
#define LV_ATTRIBUTE_LARGE_CONST
#endif

#define LV_ATTRIBUTE_IMG_DO_AM
#define LV_ATTRIBUTE_IMG_NHIET_DO
#define LV_ATTRIBUTE_IMG_SO_NGUOI
#define LV_ATTRIBUTE_IMG_THOI_TIET

/* Image descriptor definitions */
#define LV_IMG_CF_TRUE_COLOR 4

typedef struct {
    struct {
        uint32_t cf : 5;
        uint32_t always_zero : 3;
        uint32_t reserved : 2;
        uint32_t w : 11;
        uint32_t h : 11;
    } header;
    uint32_t data_size;
    const uint8_t *data;
} lv_img_dsc_t;

/* Font descriptor definitions */
#define LVGL_VERSION_MAJOR 8
#define LV_FONT_SUBPX_NONE 0
#define LV_VERSION_CHECK(x, y, z) 1

#define LV_FONT_FMT_TXT_CMAP_FORMAT0_TINY 0
#define LV_FONT_FMT_TXT_CMAP_SPARSE_TINY  1

typedef struct {
    uint32_t bitmap_index : 20;
    uint32_t adv_w : 12;
    uint8_t box_w;
    uint8_t box_h;
    int8_t ofs_x;
    int8_t ofs_y;
} lv_font_fmt_txt_glyph_dsc_t;

typedef struct {
    uint32_t range_start;
    uint16_t range_length;
    uint16_t glyph_id_start;
    const uint16_t *unicode_list;
    const void *glyph_id_ofs_list;
    uint16_t list_length;
    uint8_t type;
} lv_font_fmt_txt_cmap_t;

typedef struct {
    const uint8_t *glyph_bitmap;
    const lv_font_fmt_txt_glyph_dsc_t *glyph_dsc;
    const lv_font_fmt_txt_cmap_t *cmaps;
    const void *kern_dsc;
    uint16_t kern_scale;
    uint16_t cmap_num;
    uint8_t bpp;
    uint8_t kern_classes;
    uint8_t bitmap_format;
    void *cache;
} lv_font_fmt_txt_dsc_t;

typedef struct {
    void *dummy;
} lv_font_fmt_txt_glyph_cache_t;

typedef struct {
    const void *glyph_ids;
    const int8_t *values;
    uint32_t pair_cnt;
    uint8_t glyph_ids_size;
} lv_font_fmt_txt_kern_pair_t;

typedef struct _lv_font_t {
    const uint8_t *(*get_glyph_bitmap)(const struct _lv_font_t *, uint32_t);
    bool (*get_glyph_dsc)(const struct _lv_font_t *, void *, uint32_t, uint32_t);
    int16_t line_height;
    int16_t base_line;
    uint8_t subpx;
    int8_t underline_position;
    int8_t underline_thickness;
    uint8_t static_bitmap;
    const void *dsc;
    const struct _lv_font_t *fallback;
    void *user_data;
} lv_font_t;

/* Function prototypes */
static inline const uint8_t *lv_font_get_bitmap_fmt_txt(const lv_font_t *font, uint32_t letter) {
    (void)font; (void)letter;
    return NULL;
}

static inline bool lv_font_get_glyph_dsc_fmt_txt(const lv_font_t *font, void *dsc_out, uint32_t letter, uint32_t letter_next) {
    (void)font; (void)dsc_out; (void)letter; (void)letter_next;
    return false;
}

#endif /* LVGL_H_ */
